+package com.example;
+
+import java.io.Serializable;
+import java.util.ArrayList;
+import java.util.List;
+import org.springframework.stereotype.Service;
+
+import com.vaadin.flow.spring.annotation.VaadinSessionScope;
+
+/**
+ * Deliberately session-local and in-memory: messages remain available when a
+ * view is revisited, without making submitting the form a persistent operation.
+ */
+@Service
+@VaadinSessionScope
+public class ContactMessageStore implements Serializable {
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public void add(ContactMessage message) {
+        messages.add(0, message);
+    }
+
+    public List<ContactMessage> newestFirst() {
+        return new ArrayList<>(messages);
+    }
+}
